method.javascriptClassifier:
function classifyBarcode(raw) {
  if (raw === null || raw === undefined || String(raw).trim() === "") return {classification: "EMPTY", reason: raw == null ? "NULL" : raw === "" ? "EMPTY_STRING" : "WHITESPACE_ONLY"};
  const value = String(raw);
  if (!/^[0-9]+$/.test(value)) return {classification: "NON_GTIN_FORMAT_LENGTH", reason: "NON_NUMERIC_OR_WHITESPACE", length: value.length};
  if (![8,12,13,14].includes(value.length)) return {classification: "NON_GTIN_FORMAT_LENGTH", reason: "NUMERIC_UNSUPPORTED_LENGTH", length: value.length};
  let weightedSum = 0;
  const body = value.slice(0,-1);
  for (let i=body.length-1, position=0; i>=0; i--, position++) weightedSum += Number(body[i]) * (position % 2 === 0 ? 3 : 1);
  const expectedCheckDigit = (10 - weightedSum % 10) % 10;
  return {classification: expectedCheckDigit === Number(value.at(-1)) ? "CHECKSUM_VALID_UNVERIFIED" : "BAD_CHECKSUM", reason: "GTIN_" + value.length, length: value.length, expectedCheckDigit, actualCheckDigit: Number(value.at(-1)), weightedSum};
}

